// Small six-tile existing-raw sheet, no GPU and no video encoder.
import fs from 'node:fs';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import sharp from 'sharp';
const src='/private/tmp/ys/ys-chain-d1v1-production-r15/blender/desk',out='/private/tmp/ys/ys-chain-d1v1-render/d1-old-local-contact-20261024';
assert(!fs.existsSync(out));fs.mkdirSync(out);const hash=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const sequence=[[3618,'120.6 s before turn'],[3645,'121.5 s midway turn'],[3669,'122.3 s after turn'],[10170,'339.0 s joined valve'],[10194,'339.8 s release'],[10248,'341.6 s separated']],rows=[],layers=[];
for(let i=0;i<sequence.length;i++){const [frame,label]=sequence[i],p=src+'/'+String(frame).padStart(5,'0')+'.jpg',m=await sharp(p).metadata();assert(m.width===1080&&m.height===1920);layers.push({input:await sharp(p).resize(360,640).toBuffer(),left:i%3*360,top:Math.floor(i/3)*672+32});layers.push({input:Buffer.from(`<svg width="360" height="32"><text x="8" y="23" font-family="sans-serif" font-size="19" fill="#24180c">${label}</text></svg>`),left:i%3*360,top:Math.floor(i/3)*672});rows.push({frame,time:frame/30,path:p,sha256:hash(p),actuallyViewedByThisScript:false});}
const contact=out+'/existing-raw-six.jpg';await sharp({create:{width:1080,height:1344,channels:3,background:'#f4e8cc'}}).composite(layers).jpeg({quality:92}).toFile(contact);
const manifest={episode:'D-1',kind:'Existing original production raw, not new GPU render or final MP4',images:rows,contactSheet:contact,contactSheetSha256:hash(contact),actualEyeReviewNotInferredFromCreation:true,originalRawUnchanged:true};fs.writeFileSync(out+'/manifest.json',JSON.stringify(manifest,null,1),{flag:'wx'});console.log(JSON.stringify({contact,manifest:out+'/manifest.json',sha256:hash(out+'/manifest.json')}));
